from typing import List

class Solution:
    def minDeletionSize(self, A: List[str]) -> int:
        if not A:
            return 0

        n_cols = len(A[0])
        dp = [1] * n_cols

        for j in range(n_cols):
            for k in range(j):
                can_extend = True
                for s in A:
                    if s[k] > s[j]:
                        can_extend = False
                        break
                if can_extend:
                    dp[j] = max(dp[j], dp[k] + 1)

        longest_kept = max(dp)
        return n_cols - longest_kept
